(function(root){'use strict';
 const B=root.Biophysics,colors=['#285545','#bf7548','#597eab','#a56b91'],fmt=(x,d=1)=>Number(x).toLocaleString('ru-RU',{maximumFractionDigits:d});let H;
 function caption(view,text){view.append(H.n('p',text,'neuro-caption'));}
 function plot(view,title,yLabel,{min=-85,max=45,xLabel='Время, мс'}={}){const box=H.n('figure',undefined,'neuro-plot'),s=H.svg('svg',{viewBox:'0 0 640 265',role:'img','aria-label':title}),legend=H.n('figcaption',undefined,'neuro-legend');box.append(H.n('h3',title),s,legend);view.append(box);return(lines,markers=[])=>{s.replaceChildren();legend.replaceChildren();const end=Math.max(1,...lines.map(l=>l.points.at(-1)?.[0]||1));let lo=min,hi=max;for(const l of lines)for(const [,v] of l.points){lo=Math.min(lo,v);hi=Math.max(hi,v);}const xx=x=>58+x/end*557,yy=y=>218-(y-lo)/(hi-lo)*174;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;H.line(s,58,yy(v),615,yy(v),'#d7e0d8',1);H.label(s,4,yy(v)+5,fmt(v));H.label(s,xx(end*i/4)-8,241,fmt(end*i/4));}H.label(s,58,23,yLabel);H.label(s,285,261,xLabel);lines.forEach((l,i)=>{s.append(H.svg('polyline',{points:l.points.map(([x,y])=>xx(x)+','+yy(y)).join(' '),fill:'none',stroke:colors[i%4],'stroke-width':2.2}));const item=H.n('span',l.name);item.style.setProperty('--series',colors[i%4]);legend.append(item);});for(const x of markers)s.append(H.svg('line',{x1:xx(x),x2:xx(x),y1:35,y2:218,stroke:'#a56b91','stroke-dasharray':'3 4'}));s.dataset.samples=lines[0]?.points.length||0;};}
 const series=(trace,key,name)=>({name,points:trace.map(p=>[p.t,p[key]])});
 function details(box,title,text){const d=H.n('details'),summary=H.n('summary',title);d.append(summary,H.n('p',text));box.append(d);}
 function timeline(box,total,update){let frame=0,last=0,t=0,playing=false,playbackMs=6000;const range=H.range(box,'Момент наблюдения',0,total,0,.1,'мс',v=>{stop();t=v;update(t);}),button=H.n('button','Воспроизвести','quiet outlined');button.type='button';box.append(button);const stop=()=>{playing=false;cancelAnimationFrame(frame);button.textContent='Воспроизвести';};function tick(now){if(!playing)return;const delta=Math.min(100,now-last);last=now;t=Math.min(total,t+delta*total/playbackMs);range.set(Number(t.toFixed(1)));update(t);if(t>=total)stop();else frame=requestAnimationFrame(tick);}button.onclick=()=>{if(playing){stop();return;}if(t>=total)t=0;playing=true;last=performance.now();button.textContent='Пауза';frame=requestAnimationFrame(tick);};const hidden=()=>{if(document.hidden)stop();};document.addEventListener('visibilitychange',hidden);return{setTotal(v){stop();total=v;range.input.max=v;t=Math.min(t,total);range.set(Number(t.toFixed(1)));update(t);},setDuration(ms){playbackMs=ms;},set(v){stop();t=Math.max(0,Math.min(total,v));range.set(t);update(t);},dispose(){stop();document.removeEventListener('visibilitychange',hidden);}};}
 function action(view,c){let current=20,duration=1,interval=12,sodium=1,potassium=1;const voltage=plot(view,'Ответ мембраны','Vm, мВ'),gates=plot(view,'Активация и инактивация','Доля ворот',{min:0,max:1}),currents=plot(view,'Мембранные токи','Ток, мкА/см²',{min:-1000,max:1000}),info=H.readout(c);H.range(c,'Плотность стимулирующего тока',0,60,current,1,'мкА/см²',v=>{current=v;draw();});H.range(c,'Длительность стимула',.2,3,duration,.1,'мс',v=>{duration=v;draw();});H.range(c,'Интервал между стимулами',.5,30,interval,.5,'мс',v=>{interval=v;draw();});H.range(c,'Доступность Na⁺-каналов',0,100,100,5,'%',v=>{sodium=v/100;draw();});H.range(c,'Доступность K⁺-каналов',0,100,100,5,'%',v=>{potassium=v/100;draw();});details(c,'Параметры и уравнения','Ходжкин—Хаксли: C=1 мкФ/см²; gNa=120, gK=36, gL=0,3 мСм/см²; ENa=50, EK=−77, EL=−54,387 мВ. Классический аксон кальмара, 6,3 °C. Численное интегрирование RK4, шаг 0,01 мс. Порог и рефрактерность возникают из динамики ворот m, h, n. Время первого стимула — 5 мс; на графике пунктиром отмечены начала обоих стимулов. Токи наружу положительны.');function draw(){const r=B.hh({current,duration,interval,sodium,potassium});voltage([series(r.trace,'v','Потенциал мембраны')],[5,5+interval]);gates(['m','h','n'].map(k=>series(r.trace,k,k==='m'?'m: активация Na':k==='h'?'h: доступность Na':'n: активация K')));currents([series(r.trace,'iNa','Na⁺'),series(r.trace,'iK','K⁺'),series(r.trace,'input','Стимул')]);info.replaceChildren(H.n('strong','Потенциалов действия: '+r.spikes.length),H.n('p',r.spikes.length?'Пересечения 0 мВ: '+r.spikes.map(v=>fmt(v,2)).join('; ')+' мс.':'При этих параметрах регенеративного ответа с пересечением 0 мВ нет.'),H.n('p','Перед вторым стимулом h = '+fmt(r.atSecond.h,3)+', n = '+fmt(r.atSecond.n,3)+'. '+(r.overlap?'Стимулы перекрываются: токи складываются.':'Сравните с ответом при другом интервале.')));info.dataset.spikes=r.spikes.length;info.dataset.first=String(r.spikes.some(t=>t<5+interval));info.dataset.second=String(r.spikes.some(t=>t>=5+interval));}caption(view,'Кривые вычисляются заново. Это классическая биофизическая модель, а не измерение человеческого нейрона.');draw();}
 function synapse(view,c){
  let kind='chemical',calcium=1,frequency=20,coupling=3,source=0,delay=.8,result,now=21.8;const scene=H.n('div',undefined,'synapse-scene-controls'),anatomy=SynapseView.create(view,scene,H),voltage=plot(view,'Ответ мембраны','Vm, мВ',{min:-65,max:-20}),cleft=plot(view,'Сигнал медиатора в щели','Условные единицы',{min:0,max:1}),conductance=plot(view,'Постсинаптическая проводимость','g, нСм',{min:0,max:4}),resources=plot(view,'Готовый к выделению пул','Доля пула',{min:0,max:1}),gapCurrent=plot(view,'Ток между клетками','I1→2, пА',{min:-15,max:15}),info=H.readout(c);
  H.select(c,'Тип синапса',[['chemical','Химический · глутамат/AMPA'],['electrical','Электрический · gap junction']],kind,v=>{kind=v;draw();});
  const ca=H.range(c,'Пресинаптический Ca²⁺',0,2,1,.1,'отн. ед.',v=>{calcium=v;draw();});H.range(c,'Частота серии из четырёх стимулов',5,80,frequency,5,'Гц',v=>{frequency=v;draw();});const lag=H.range(c,'Синаптическая задержка',0,3,delay,.1,'мс',v=>{delay=v;draw();}),gap=H.range(c,'Проводимость щелевого контакта',0,10,coupling,.5,'нСм',v=>{coupling=v;draw();}),src=H.select(c,'Стимулируемая клетка',[['0','Клетка 1'],['1','Клетка 2']],'0',v=>{source=Number(v);draw();});c.append(scene);
  const stages=H.n('div',undefined,'neuro-parts');for(const[title,offset,release]of[['До стимула',-.4,false],['Вход Ca²⁺',.3,false],['Слияние везикулы',.2,true],['Медиатор и рецепторы',1.2,true],['После удаления медиатора',9,true]]){const b=H.n('button',title,'quiet outlined');b.type='button';b.onclick=()=>time.set((release?result.events[0].t:result.stimulusTimes[0])+offset);stages.append(b);}anatomy.timeControls.append(stages);
  const time=timeline(anatomy.timeControls,270.8,t=>{now=t;if(result){anatomy(kind,result,now);cursor();}});time.setDuration(24000);const tempo=H.n('details');tempo.append(H.n('summary','Темп воспроизведения'));anatomy.timeControls.append(tempo);H.select(tempo,'Темп анимации',[['1','Медленно'],['2','Средне'],['4','Быстро']],'1',v=>time.setDuration(24000/Number(v)));
  details(c,'Расчёт и границы реализма','Химический контакт: ожидаемое выделение p·R, p=0,6·Ca⁴/(Ca⁴+0,5⁴); восстановление пула τ=180 мс. После выбранной задержки появляется условный сигнал медиатора с τ=1,2 мс; это не концентрация в моль/л и не пространственная диффузия. Проводимость — отдельная разность экспонент τ=0,5 и 6 мс; Erev=0 мВ. Пассивная постсинаптическая мембрана C=100 пФ, gL=5 нСм. Это один глутаматергический пример, не все химические синапсы. Пресинаптический ПД, микродомены Ca²⁺ и молекулярное связывание не вычисляются. Электрический контакт: две одинаковые пассивные клетки, I1→2=ggap(V1−V2); стимул 250 пА на 2 мс. Он симметричный, без выпрямления и везикулярного выделения. Геометрия, частицы и скорости иллюстративны.');
  function cursor(){const end=result.trace.at(-1).t,x=58+Math.min(now,end)/end*557;for(const s of view.querySelectorAll('.neuro-plot svg')){let l=s.querySelector('.synapse-cursor');if(!l){l=H.svg('line',{class:'synapse-cursor',y1:35,y2:218,stroke:'#a56b91','stroke-dasharray':'3 4'});s.append(l);}l.setAttribute('x1',x);l.setAttribute('x2',x);}}
  function draw(){result=B.synapse({kind,calcium,frequency,coupling,source,delay});ca.input.parentElement.hidden=lag.input.parentElement.hidden=kind!=='chemical';gap.input.parentElement.hidden=src.parentElement.hidden=kind!=='electrical';stages.hidden=kind!=='chemical';voltage(kind==='chemical'?[series(result.trace,'v2','Постсинаптическая клетка')]:[series(result.trace,'v1','Клетка 1'),series(result.trace,'v2','Клетка 2')]);cleft([series(result.trace,'cleftSignal','Условный сигнал, не концентрация')]);conductance([series(result.trace,'g','Проводимость рецепторов')]);resources([series(result.trace,'reserve','Доступный резерв')]);gapCurrent([series(result.trace,'gapCurrent','Ток из клетки 1 в клетку 2')]);const figures=view.querySelectorAll('.neuro-plot');[1,2,3].forEach(i=>figures[i].hidden=kind!=='chemical');figures[4].hidden=kind!=='electrical';const amounts=result.events.map(e=>fmt(e.released*100));info.replaceChildren(H.n('strong',kind==='chemical'?'Вероятность выделения: '+fmt(result.releaseProbability*100)+' %':'Взаимное электрическое сопряжение'),H.n('p',kind==='chemical'?'Ожидаемая доля исходного пула при стимулах: '+amounts.join(' → ')+' %. При частой серии пул истощается. Сигнал медиатора и проводимость показаны отдельно.':'Смените стимулируемую клетку: знак тока меняется. Везикулярное выделение и Ca²⁺ в расчёте этого контакта не участвуют.'));info.dataset.release=String(kind==='chemical'&&calcium>0);time.setTotal(result.trace.at(-1).t);anatomy(kind,result,now);cursor();}
  const graphs=H.n('details',undefined,'synapse-graphs'),graphGrid=H.n('div',undefined,'synapse-plot-grid');graphs.append(H.n('summary','Подробные графики: медиатор, проводимость, ток и резерв'),graphGrid);view.querySelectorAll('.neuro-plot').forEach(f=>graphGrid.append(f));view.append(graphs);const reveal=H.n('button','Вернуться к 3D-модели','quiet outlined');reveal.type='button';reveal.onclick=anatomy.reveal;c.append(reveal);draw();time.set(21.8);return()=>{time.dispose();anatomy.dispose();};
 }
 function receptor(view,c){let family='ion',chloride=8,voltage=-65,present=true,conductance=5;const vm=plot(view,'Ответ мембраны','Vm, мВ',{min:-90,max:-15}),g=plot(view,'Изменение проводимости','g, нСм',{min:0,max:20}),info=H.readout(c);H.select(c,'Рецептор',[['ion','GABA_A · Cl⁻-канал'],['meta','GABA_B · G-белок → K⁺']],'ion',v=>{family=v;draw();});const cl=H.range(c,'Внутриклеточный Cl⁻',2,60,chloride,1,'ммоль/л',v=>{chloride=v;draw();});H.range(c,'Исходный Vm',-90,-35,voltage,1,'мВ',v=>{voltage=v;draw();});H.range(c,'Максимальная проводимость',0,20,conductance,1,'нСм',v=>{conductance=v;draw();});H.check(c,'Подать лиганд на 20–80 мс',true,v=>{present=v;draw();});details(c,'Уравнения и ограничения','ECl рассчитан по Нернсту при 37 °C и [Cl⁻]снаружи=120 ммоль/л. GABA_A представлен только Cl⁻, без HCO₃⁻. GABA_B — иллюстративный каскад связывание → G-белок → K⁺, EK=−90 мВ. C=100 пФ, gL=5 нСм; I=g(V−Erev). Знак тока и изменение Vm не равнозначны изменению вероятности ПД: повышение проводимости снижает входное сопротивление. Константы связывания и каскада не подогнаны к эксперименту.');function draw(){const r=B.receptor({family,chloride,voltage,present,conductance});cl.input.parentElement.hidden=family!=='ion';vm([series(r.trace,'v','Vm')]);g([series(r.trace,'g',family==='ion'?'GABA_A':'GABA_B → K⁺')]);info.replaceChildren(H.n('strong','Erev = '+fmt(r.eRev)+' мВ'),H.n('p',(family==='ion'?'Cl⁻-канал':'G-белок → K⁺-проводимость')+' · '+(r.direction==='depolarizing'?'деполяризующий':r.direction==='shunting'?'почти у реверсии, шунтирующий':'гиперполяризующий')+' вклад при исходном Vm.'),H.n('p','Входное сопротивление: '+fmt(r.inputResistanceBefore)+' → '+fmt(r.inputResistanceDuring)+' МОм. Деполяризация сама по себе не доказывает возбуждение.'));info.dataset.reversal=r.eRev;}draw();}
 function transmitter(view,c){let molecule='dopamine',frequency=20,uptakeBlock=0,enzymeBlock=0,calcium=true;const pool=plot(view,'Распределение медиатора','Количество, отн. ед.',{min:0,max:160}),cleft=plot(view,'Медиатор в щели','Количество, отн. ед.',{min:0,max:100}),info=H.readout(c);H.select(c,'Медиатор',[['dopamine','Дофамин'],['serotonin','Серотонин'],['gaba','ГАМК'],['glutamate','Глутамат'],['ach','Ацетилхолин']],molecule,v=>{molecule=v;draw();});H.range(c,'Частота стимуляции',1,80,frequency,1,'Гц',v=>{frequency=v;draw();});const uptake=H.range(c,'Ингибирование обратного захвата',0,100,0,5,'%',v=>{uptakeBlock=v/100;draw();}),enzyme=H.range(c,'Ингибирование ацетилхолинэстеразы',0,100,0,5,'%',v=>{enzymeBlock=v/100;draw();});H.check(c,'Доступен вход Ca²⁺',true,v=>{calcium=v;draw();});details(c,'Пулы и баланс вещества','Пулы: цитозоль, везикулы, щель и удалённое вещество. Синтез пополняет систему, упаковка переносит в везикулы, стимул высвобождает 18 % доступного пула. Захват насыщаемый (Михаэлис—Ментен). В модели дофамин/5-HT возвращаются в терминаль, глутамат уходит в глиальный пул; ГАМК частично возвращается. Ацетилхолин гидролизуется: обратного захвата целой молекулы нет. Ресинтез из холина отдельно не моделируется. Единицы и скорости условны; метаболические пути сведены к стокам.');function draw(){const r=B.transmitter({molecule,frequency,uptakeBlock,enzymeBlock,calcium}),baseline=B.transmitter({molecule,frequency,calcium});uptake.input.parentElement.hidden=molecule==='ach';enzyme.input.parentElement.hidden=molecule!=='ach';pool([series(r.trace,'cyt','Цитозоль'),series(r.trace,'vesicles','Везикулы'),series(r.trace,'removed','Удалено')]);cleft([series(r.trace,'cleft','Выбранное условие'),series(baseline.trace,'cleft','Без ингибирования')]);info.replaceChildren(H.n('strong',molecule==='ach'?'Гидролиз ацетилхолина':'Захват и метаболизм'),H.n('p',molecule==='ach'?'После гидролиза в терминаль возвращается холин. Ингибирование захвата целого ацетилхолина здесь не применяется.':'Высвобождение зависит от доступного пула; блок захвата меняет накопление и повторное использование.'),H.n('p','Ошибка баланса: '+r.balance.toExponential(1)+' отн. ед. Сумма пулов и удалённого равна исходному количеству плюс синтез.'));info.dataset.balance=r.balance;}caption(view,'Шкала времени дана в мс; количество и скорости иллюстративны, без привязки к концентрациям человеческого мозга.');draw();}
 function myelin(view,c){let damage=0,leak=4,extent=2,result,now=0;const s=H.diagram(view,'Мембранный потенциал вдоль 25 электрических компартментов'),vm=plot(view,'Дистальный участок аксона','Vm, мВ'),info=H.readout(c);H.range(c,'Изменение мембраны в очаге',0,100,0,10,'% шкалы модели',v=>{damage=v/100;draw();});H.range(c,'Утечка в очаге',.1,12,leak,.1,'мСм/см² при максимуме',v=>{leak=v;draw();});H.range(c,'Протяжённость очага',1,8,extent,1,'компартментов',v=>{extent=v;draw();});const time=timeline(c,45,t=>{now=t;heat();});details(c,'Как возникает задержка или блок','25 связанных электрических компартментов, активные HH-узлы через каждые три. Межузловая C=0,06 → 1 мкФ/см²; утечка 0,003 → выбранное значение мСм/см². Удельные эффективные параметры и осевая связь иллюстративны. Активные узлы не выключаются при демиелинизации. Блок возникает, если деполяризация не достигает следующего активного участка; отдельного правила «повреждение > порог» нет. Геометрические длины не заданы, поэтому скорость в м/с не вычисляется.');function heat(){if(!result)return;const p=result.trace.reduce((a,b)=>Math.abs(b.t-now)<Math.abs(a.t-now)?b:a);s.replaceChildren();H.label(s,20,28,'Vm вдоль аксона · '+fmt(p.t)+' мс');for(let j=0;j<25;j++){const v=p.voltage[j],warm=Math.max(0,Math.min(1,(v+80)/120));s.append(H.svg('rect',{x:15+j*24,y:80,width:21,height:65,rx:7,fill:`hsl(${210-warm*180} 45% ${70-warm*20}%)`,stroke:j>=10&&j<10+extent?'#af4d42':'#52675d','stroke-width':j>=10&&j<10+extent?3:1}));if(j%3===0)H.label(s,18+j*24,170,'•');}H.label(s,20,205,'• активный узел   рамка: очаг');H.label(s,20,248,'Синий −80 мВ → красный +40 мВ');s.dataset.time=p.t;s.dataset.distal=p.voltage.at(-1);}function draw(){result=B.myelin({damage,leak,extent});const base=B.myelin();vm([{name:'Выбранное условие',points:result.trace.map(p=>[p.t,p.voltage.at(-1)])},{name:'Интактная модель',points:base.trace.map(p=>[p.t,p.voltage.at(-1)])}]);info.replaceChildren(H.n('strong',result.conducts?'Проведение сохранено':'Дистальный ПД не возник'),H.n('p',result.conducts?'Задержка между первым и последним участком: '+fmt(result.delay,2)+' мс; без очага '+fmt(base.delay,2)+' мс.':'Недостаточный ток в следующих участках при выбранных ёмкости, утечке и длине очага. Небольшое повреждение может лишь замедлять проведение.'),H.n('p','Это электрическая модель, шкала не равна проценту поражения ткани.'));info.dataset.conducts=result.conducts;heat();}draw();time.set(6);return()=>time.dispose();}
 function circuit(view,c){let excitation=6,inhibition=2,synchronous=true,inhibitoryReversal=-75;const vm=plot(view,'Интегрирование входов','Vm, мВ',{min:-85,max:-45}),g=plot(view,'Синаптические проводимости','g, нСм',{min:0,max:100}),info=H.readout(c);H.range(c,'Возбуждающие входы',0,12,excitation,1,'',v=>{excitation=v;draw();});H.range(c,'Тормозные входы',0,12,inhibition,1,'',v=>{inhibition=v;draw();});H.check(c,'Синхронные возбуждающие входы',true,v=>{synchronous=v;draw();});H.range(c,'Реверсия тормозного входа',-85,-55,inhibitoryReversal,1,'мВ',v=>{inhibitoryReversal=v;draw();});details(c,'Модель интегрирования','Conductance-based leaky integrate-and-fire: C=200 пФ, gL=10 нСм, EL=−65 мВ, порог −50, сброс −65, рефрактерность 2 мс. На один вход — 4 нСм; τE=5, τI=10 мс. Eexc=0 мВ; Einh регулируется. Четыре серии входов. Разнесённые возбуждающие входы приходят с шагом 3 мс. Пунктир отмечает события ПД; форма самого ПД не моделируется.');function draw(){const r=B.circuit({excitation,inhibition,synchronous,inhibitoryReversal});vm([series(r.trace,'v','Vm · пунктир: импульсы')],r.spikes);g([series(r.trace,'gE','Возбуждение'),series(r.trace,'gI','Торможение')]);info.replaceChildren(H.n('strong','Импульсов: '+r.spikes.length),H.n('p','Ток зависит от g и движущей силы (Vm−Erev). Увеличение проводимости около Vm может шунтировать возбуждение даже без большой гиперполяризации.'));info.dataset.spikes=r.spikes.length;}draw();}
 function pharmacology(view,c){let mode='binding',agonist=1,partial=1,antagonist=0,efficacy=.4,uptakeBlock=0;const binding=plot(view,'Ответ при конкуренции лигандов','Ответ, доля максимума',{min:0,max:1,xLabel:'Фоновый полный агонист, [A]/KdA'}),clearance=plot(view,'Удаление дофамина','Количество в щели, отн. ед.',{min:0,max:100}),info=H.readout(c);H.select(c,'Механизм',[['binding','Конкуренция за рецептор'],['uptake','Ингибирование захвата']],mode,v=>{mode=v;draw();});const a=H.range(c,'Фоновый полный агонист',0,10,agonist,.1,'[A]/KdA',v=>{agonist=v;draw();}),p=H.range(c,'Частичный агонист',0,10,partial,.1,'[P]/KdP',v=>{partial=v;draw();}),ant=H.range(c,'Конкурентный антагонист',0,10,antagonist,.1,'[B]/KdB',v=>{antagonist=v;draw();}),e=H.range(c,'Эффективность частичного агониста',0,1,efficacy,.05,'доля',v=>{efficacy=v;draw();}),u=H.range(c,'Ингибирование обратного захвата',0,100,0,5,'%',v=>{uptakeBlock=v/100;draw();});details(c,'Равновесие и ограничения','Один класс независимых рецепторов, конкурентное равновесие. Доли: A/Z, P/Z, B/Z, 1/Z; Z=1+A+P+B, концентрации нормированы на соответствующие Kd. Ответ=A/Z+эффективность·P/Z. Нет рецепторного резерва, кооперативности или адаптации; частичный агонист может уменьшать ответ на фоне полного. Модель захвата использует те же пулы, что NeurotransmitterLab. Это не дозы и не прогноз лечения.');function draw(){for(const ctrl of[a,p,ant,e])ctrl.input.parentElement.hidden=mode!=='binding';u.input.parentElement.hidden=mode!=='uptake';view.querySelectorAll('.neuro-plot')[0].hidden=mode!=='binding';view.querySelectorAll('.neuro-plot')[1].hidden=mode!=='uptake';if(mode==='binding'){const r=B.occupancy({agonist,partial,antagonist,efficacy}),base=B.occupancy({agonist});binding([{name:'С конкурирующими лигандами',points:Array.from({length:101},(_,i)=>[i/10,B.occupancy({agonist:i/10,partial,antagonist,efficacy}).response])},{name:'Только полный агонист',points:Array.from({length:101},(_,i)=>[i/10,B.occupancy({agonist:i/10}).response])}],[agonist]);info.replaceChildren(H.n('strong','Ответ: '+fmt(r.response*100)+' %'),H.n('p','Без конкурентов: '+fmt(base.response*100)+' %. Занятость полным / частичным / антагонистом / свободно: '+[r.full,r.partial,r.antagonist,r.free].map(v=>fmt(v*100)).join(' / ')+' %.'),H.n('p','Частичный агонист не всегда усиливает ответ: при высоком фоне он вытесняет полный.'));info.dataset.response=r.response;}else{const r=B.transmitter({uptakeBlock}),base=B.transmitter();clearance([series(r.trace,'cleft','Блок захвата'),series(base.trace,'cleft','Без блока')]);info.replaceChildren(H.n('strong','Блок захвата: '+fmt(uptakeBlock*100)+' %'),H.n('p','Изменяются удаление, накопление и возврат в терминаль; это не прямая мера клинического эффекта.'));}}draw();}
 function pathology(view,c){let example='myelin',change=.5;const graph=plot(view,'Сопоставление одного механизма','Нормированный показатель',{min:0,max:1.2}),info=H.readout(c);H.select(c,'Пример механизма',[['myelin','Демиелинизация · электрическое проведение'],['dopamine','Дофамин · число функционирующих терминалей'],['network','Сеть · уменьшение тормозных входов']],example,v=>{example=v;draw();});H.range(c,'Изменение выбранного звена',0,100,50,10,'% шкалы модели',v=>{change=v/100;draw();});details(c,'Что сравнивается','Без произвольной линейной шкалы тяжести. Демиелинизация: компартментная модель MyelinLab, очаг 5 участков, утечка 4. Дофамин: пулы медиатора, доля функционирующих терминалей 1−изменение. Сеть: модель проводимостей с 6 возбуждающими и от 6 до 0 тормозных входов. Параметр не соответствует проценту утраты нейронов у пациента; ни один из этих опытов не представляет заболевание целиком.');function draw(){let lines,text,title;if(example==='myelin'){const base=B.myelin(),r=B.myelin({damage:change,extent:5});lines=[{name:'Изменённый участок',points:r.trace.map(p=>[p.t,(p.voltage.at(-1)+80)/120])},{name:'Интактная модель',points:base.trace.map(p=>[p.t,(p.voltage.at(-1)+80)/120])}];title=r.conducts?'Проведение: '+fmt(r.delay,2)+' мс':'Дистальный ответ не возник';text='Показан Vm последнего участка: 0 соответствует −80 мВ, 1 соответствует +40 мВ.';}else if(example==='dopamine'){const base=B.transmitter(),r=B.transmitter({terminals:1-change}),peak=Math.max(1,...base.trace.map(p=>p.cleft));lines=[{name:'Меньше терминалей',points:r.trace.map(p=>[p.t,p.cleft/peak])},{name:'Исходная модель',points:base.trace.map(p=>[p.t,p.cleft/peak])}];title='Дофаминергическая передача';text='Количество в щели нормировано на исходный пик. Модель не воспроизводит петли базальных ганглиев, компенсацию и симптомы болезни Паркинсона.';}else{const base=B.circuit({inhibition:6}),r=B.circuit({inhibition:Math.round(6*(1-change))});lines=[{name:'Меньше тормозных входов',points:r.trace.map(p=>[p.t,(p.v+85)/40])},{name:'Исходная модель',points:base.trace.map(p=>[p.t,(p.v+85)/40])}];title='Импульсов: '+r.spikes.length+' (исходно '+base.spikes.length+')';text='Vm нормирован: 0 = −85 мВ, 1 = −45 мВ. Снижение торможения меняет возбудимость этой модели; клинический приступ из этого не следует.';}graph(lines);info.replaceChildren(H.n('strong',title),H.n('p',text));info.dataset.mechanism=example;}draw();}
 function cable(view,c){let distance=300,diameter=1,membraneResistance=10000;const graph=plot(view,'Пассивное распространение по отростку','ΔVm, мВ',{min:0,max:10,xLabel:'Расстояние, мкм'}),info=H.readout(c);H.range(c,'Расстояние от входа',0,1500,distance,50,'мкм',v=>{distance=v;draw();});H.range(c,'Диаметр отростка',.2,10,diameter,.2,'мкм',v=>{diameter=v;draw();});H.range(c,'Удельное сопротивление мембраны',1000,40000,membraneResistance,1000,'Ом·см²',v=>{membraneResistance=v;draw();});function draw(){const r=B.cable({distance,diameter,membraneResistance});graph([{name:'Стационарный ответ на вход 10 мВ',points:r.profile}],[distance]);info.replaceChildren(H.n('strong','λ = '+fmt(r.lambda)+' мкм'),H.n('p','На выбранном расстоянии остаётся '+fmt(r.attenuation*100)+' %: ΔVm = '+fmt(10*r.attenuation,2)+' мВ. τ = '+fmt(r.tau)+' мс.'));}caption(view,'Пассивный бесконечный однородный кабель: ΔV(x)=10·exp(−x/λ); λ=√(d·Rm/4Ra), Ra=150 Ом·см, Cm=1 мкФ/см². Здесь нет регенерации ПД и разветвлений; это стационарный профиль.');draw();}
 const renderers={action,synapse,receptor,transmitter,myelin,circuit,pharmacology,pathology};root.NeuroSim={mount(id,view,controls,helpers){H=helpers;return renderers[id](view,controls);},cable(view,c,helpers){H=helpers;return cable(view,c);}};
})(globalThis);
